// SPDX-License-Identifier: MIT
pragma solidity 0.8.25;

import {TopUpGateway} from "contracts/0.8.25/TopUpGateway.sol";
import {TopUpData, BeaconRootData, ValidatorWitness} from "contracts/common/interfaces/TopUpWitness.sol";
import {pack} from "contracts/common/lib/GIndex.sol";
import {SSZ} from "contracts/common/lib/SSZ.sol";

interface GatewayVm {
    function mockCall(address, bytes calldata, bytes calldata) external;
    function warp(uint256) external;
    function roll(uint256) external;
    function store(address,bytes32,bytes32) external;
}

// The real gateway/verifier are inherited without overriding any operation.
// Internal setters and role grant prepare a standalone fixture, not a proxy deployment.
contract GatewayWitnessHarness is TopUpGateway {
    Storage private layoutOnly; // Compiler type-layout witness; real reads use the namespace.
    constructor(address locator, uint256 epochSize)
        TopUpGateway(locator, pack(150 * (1 << 40),40), pack(150 * (1 << 40),40),0,epochSize)
    {
        _grantRole(TOP_UP_ROLE,msg.sender);
        _setMaxValidatorsPerTopUp(8);
        _setMinBlockDistance(1);
        _setMaxRootAge(100);
        _setTopUpBalanceLimits(64_000_000_000,1_000_000_000);
    }
}

// Only the router boundary is a recorder; no funding or module effect is claimed.
contract GatewayRouterRecorder {
    bytes32 public credentials;
    bytes32 public captured;
    uint256 public calls;
    function setCredentials(bytes32 value) external { credentials=value; }
    function getStakingModuleWithdrawalCredentials(uint256) external view returns(bytes32) { return credentials; }
    function topUp(uint256 moduleId,uint256[] calldata keys,uint256[] calldata operators,bytes[] calldata pubkeys,uint256[] calldata limits) external {
        calls++;
        captured=keccak256(abi.encode(moduleId,keys,operators,pubkeys,limits));
    }
}
contract GatewayLocatorFixture {
    address public immutable stakingRouter;
    constructor(address router) { stakingRouter=router; }
}

contract TopupGatewayWitnessBatchTest {
    GatewayVm constant vm=GatewayVm(address(uint160(uint256(keccak256("hevm cheat code")))));
    address constant ROOTS=0x000F3df6D732807Ef1319fB7B8bB8522d0Beac02;
    bytes32 constant WC=bytes32((uint256(2)<<248)|12345);
    GatewayRouterRecorder router;
    GatewayWitnessHarness gateway;

    function setUp() public {
        vm.warp(1000); vm.roll(100);
        router=new GatewayRouterRecorder(); router.setCredentials(WC);
        gateway=new GatewayWitnessHarness(address(new GatewayLocatorFixture(address(router))),32);
    }
    function pair(bytes32 a,bytes32 b) internal pure returns(bytes32) { return sha256(abi.encodePacked(a,b)); }
    function le(uint256 n) internal pure returns(bytes32 out) {
        for(uint256 j;j<32;j++) out|=bytes32(((n>>(8*j))&255)<<(248-8*j));
    }
    function pubkey(bytes32 seed,uint256 i) internal pure returns(bytes memory) {
        return abi.encodePacked(keccak256(abi.encode(seed,i)),bytes16(keccak256(abi.encode(i,seed))));
    }
    function leaf(ValidatorWitness memory w) internal pure returns(bytes32) {
        bytes32[8] memory nodes=[sha256(abi.encodePacked(w.pubkey,bytes16(0))),WC,le(w.effectiveBalance),le(w.slashed?1:0),le(w.activationEligibilityEpoch),le(w.activationEpoch),le(w.exitEpoch),le(w.withdrawableEpoch)];
        for(uint256 width=8;width>1;width/=2) for(uint256 i;i<width/2;i++) nodes[i]=pair(nodes[2*i],nodes[2*i+1]);
        return nodes[0];
    }
    // Independent sparse validator list of length2/capacity2^40; named state slot11,
    // opaque other state roots, then header state slot3. No Lido SSZ helper is used.
    function fixture(bytes32 seed,uint64 effective0,uint64 effective1,bool slashed0,bool exited1)
        internal pure returns(TopUpData memory d,bytes32 root)
    {
        d.moduleId=7;
        d.beaconRootData=BeaconRootData(1000,4096,18);
        d.keyIndices=new uint256[](2); d.keyIndices[0]=17;d.keyIndices[1]=33;
        d.operatorIds=new uint256[](2); d.operatorIds[0]=4;d.operatorIds[1]=8;
        d.validatorIndices=new uint256[](2);d.validatorIndices[1]=1;
        d.pendingBalanceGwei=new uint256[](2);
        d.validatorWitness=new ValidatorWitness[](2);
        for(uint256 i;i<2;i++) d.validatorWitness[i]=ValidatorWitness(new bytes32[](50),pubkey(seed,i),i==0?effective0:effective1,0,1,(i==1&&exited1)?2:type(uint64).max,type(uint64).max,i==0&&slashed0);
        bytes32[2] memory leaves=[leaf(d.validatorWitness[0]),leaf(d.validatorWitness[1])];
        d.validatorWitness[0].proofValidator[0]=leaves[1];d.validatorWitness[1].proofValidator[0]=leaves[0];
        bytes32 registry=pair(leaves[0],leaves[1]); bytes32 zero=pair(bytes32(0),bytes32(0));
        for(uint256 depth=1;depth<40;depth++) {
            d.validatorWitness[0].proofValidator[depth]=zero;d.validatorWitness[1].proofValidator[depth]=zero;
            registry=pair(registry,zero);zero=pair(zero,zero);
        }
        bytes32[64] memory state;
        for(uint256 i;i<37;i++) state[i]=sha256(abi.encode("opaque Electra field",i));
        state[11]=pair(registry,le(2));
        for(uint256 i;i<2;i++) d.validatorWitness[i].proofValidator[40]=le(2);
        uint256 pos=11;
        for(uint256 depth;depth<6;depth++) {
            for(uint256 i;i<2;i++) d.validatorWitness[i].proofValidator[41+depth]=state[pos^1];
            uint256 width=64>>depth;
            for(uint256 j;j<width/2;j++) state[j]=pair(state[2*j],state[2*j+1]);
            pos/=2;
        }
        bytes32[8] memory header=[le(4096),le(18),sha256("parent"),state[0],sha256("body"),bytes32(0),bytes32(0),bytes32(0)];
        pos=3;
        for(uint256 depth;depth<3;depth++) {
            for(uint256 i;i<2;i++) d.validatorWitness[i].proofValidator[47+depth]=header[pos^1];
            uint256 width=8>>depth;
            for(uint256 j;j<width/2;j++) header[j]=pair(header[2*j],header[2*j+1]);
            pos/=2;
        }
        root=header[0];
    }
    function anchor(TopUpData memory d,bytes32 root) internal { vm.mockCall(ROOTS,abi.encode(d.beaconRootData.childBlockTimestamp),abi.encode(root)); }
    function reject(TopUpData memory d,bytes memory expected) internal {
        (bool ok,bytes memory reason)=address(gateway).call(abi.encodeCall(gateway.topUp,(d)));
        require(!ok&&keccak256(reason)==keccak256(expected),"wrong rejection");
        require(router.calls()==0,"router entered on rejected batch");
    }
    function err(bytes4 selector) internal pure returns(bytes memory) { return abi.encodeWithSelector(selector); }
    function headroom(uint256 effective,uint256 pending,bool excluded) internal pure returns(uint256) {
        if(excluded) return 0;
        uint256 total=effective+pending;
        if(total>=64_000_000_000) return 0;
        uint256 room=64_000_000_000-total;
        return room<1_000_000_000?0:room*1 gwei;
    }
    function testFuzz_actualWitnessesProduceRouterArguments(bytes32 seed,uint64 e0,uint64 e1,uint64 p0,uint64 p1,bool slashed,bool exited) public {
        (TopUpData memory d,bytes32 root)=fixture(seed,e0,e1,slashed,exited);
        d.pendingBalanceGwei[0]=p0;d.pendingBalanceGwei[1]=p1;anchor(d,root);
        uint256[] memory limits=new uint256[](2);
        limits[0]=headroom(e0,p0,slashed);limits[1]=headroom(e1,p1,exited);
        bytes[] memory keys=new bytes[](2);keys[0]=d.validatorWitness[0].pubkey;keys[1]=d.validatorWitness[1].pubkey;
        gateway.topUp(d);
        require(router.calls()==1&&router.captured()==keccak256(abi.encode(d.moduleId,d.keyIndices,d.operatorIds,keys,limits)),"wrong produced arrays");
        require(gateway.getLastTopUpTimestamp()==((limits[0]+limits[1]>0)?1000:0),"limits timing");
    }
    function test_positiveLimitsAndPendingPairs() public {
        (TopUpData memory d,bytes32 root)=fixture(bytes32(uint256(7)),32_000_000_000,40_000_000_000,false,false);
        d.pendingBalanceGwei[0]=2_000_000_000;d.pendingBalanceGwei[1]=3_000_000_000;anchor(d,root);
        uint256[] memory limits=new uint256[](2);limits[0]=30 ether;limits[1]=21 ether;
        bytes[] memory keys=new bytes[](2);keys[0]=d.validatorWitness[0].pubkey;keys[1]=d.validatorWitness[1].pubkey;
        gateway.topUp(d);
        require(router.captured()==keccak256(abi.encode(d.moduleId,d.keyIndices,d.operatorIds,keys,limits)),"units/pairing");
        require(gateway.getLastTopUpTimestamp()==1000,"positive limits write");
    }
    function testFuzz_headroomAndMinimum(bytes32 seed,uint64 effectiveSeed,uint64 pendingSeed) public {
        uint64 effective=effectiveSeed%64_000_000_001;
        uint64 pending=pendingSeed%16_000_000_001;
        (TopUpData memory d,bytes32 root)=fixture(seed,effective,63_000_000_001,false,false);
        d.pendingBalanceGwei[0]=pending;anchor(d,root);
        uint256[] memory limits=new uint256[](2);limits[0]=headroom(effective,pending,false);
        bytes[] memory keys=new bytes[](2);keys[0]=d.validatorWitness[0].pubkey;keys[1]=d.validatorWitness[1].pubkey;
        gateway.topUp(d);
        require(router.captured()==keccak256(abi.encode(d.moduleId,d.keyIndices,d.operatorIds,keys,limits)),"headroom/minimum");
        require(gateway.getLastTopUpTimestamp()==(limits[0]>0?1000:0),"threshold timing");
    }
    function test_guardPriorityAndVerifiedFields() public {
        (TopUpData memory d,bytes32 root)=fixture(bytes32(0),32_000_000_000,32_000_000_000,false,false);anchor(d,root);
        d.validatorWitness[1].pubkey=new bytes(47);d.validatorIndices[1]=0;
        reject(d,err(TopUpGateway.WrongPubkeyLength.selector));
        d.validatorWitness[1].pubkey=pubkey(bytes32(0),1);
        reject(d,err(TopUpGateway.InvalidValidatorIndicesSortOrder.selector));d.validatorIndices[1]=1;
        d.validatorWitness[0].activationEpoch=129;d.validatorWitness[0].proofValidator[0]^=bytes32(uint256(1));
        reject(d,err(TopUpGateway.ValidatorIsNotActivated.selector));d.validatorWitness[0].activationEpoch=1;
        d.pendingBalanceGwei[0]=type(uint256).max;
        reject(d,err(SSZ.InvalidProof.selector));d.validatorWitness[0].proofValidator[0]^=bytes32(uint256(1));
        reject(d,abi.encodeWithSignature("Panic(uint256)",0x11));
        d.pendingBalanceGwei[0]=0;router.setCredentials(bytes32((uint256(2)<<248)|6789));
        reject(d,err(SSZ.InvalidProof.selector));
    }
    function test_excludedStillVerifiedButSkipPendingOverflow() public {
        (TopUpData memory d,bytes32 root)=fixture(bytes32(0),32_000_000_000,32_000_000_000,true,true);anchor(d,root);
        d.pendingBalanceGwei[0]=type(uint256).max;d.pendingBalanceGwei[1]=type(uint256).max;
        d.validatorWitness[0].proofValidator[0]^=bytes32(uint256(1));reject(d,err(SSZ.InvalidProof.selector));
        d.validatorWitness[0].proofValidator[0]^=bytes32(uint256(1));gateway.topUp(d);
        require(router.calls()==1&&gateway.getLastTopUpTimestamp()==0,"excluded amount/timing");
    }
    function test_arrayAdmissionAndZeroEpochDivisor() public {
        (TopUpData memory d,bytes32 root)=fixture(bytes32(0),32_000_000_000,32_000_000_000,false,false);anchor(d,root);
        d.pendingBalanceGwei=new uint256[](1);reject(d,err(TopUpGateway.WrongArrayLength.selector));
        d.pendingBalanceGwei=new uint256[](2);
        gateway=new GatewayWitnessHarness(address(new GatewayLocatorFixture(address(router))),0);
        reject(d,abi.encodeWithSignature("Panic(uint256)",0x12));
    }
    function testFuzz_actualConfigWordReads(uint256 first,uint256 second) public {
        bytes32 position=0x22e512057841e2bc1e6d80030c8bb8b4935377af2e64ba9bf8e6a3e88fb32200;
        vm.store(address(gateway),position,bytes32(first));
        vm.store(address(gateway),bytes32(uint256(position)+1),bytes32(second));
        require(gateway.getMaxValidatorsPerTopUp()==uint64(first),"count word");
        require(gateway.getTargetBalanceGwei()==uint64(first>>160),"target word");
        require(gateway.getMinTopUpGwei()==uint64(second),"minimum word");
    }
}

contracts/0.8.25/CLValidatorVerifier.sol.content:
// SPDX-FileCopyrightText: 2025 Lido <info@lido.fi>
// SPDX-License-Identifier: GPL-3.0

pragma solidity 0.8.25;

import {GIndex, pack, concat} from "contracts/common/lib/GIndex.sol";
import {SSZ} from "contracts/common/lib/SSZ.sol";
import {BLS12_381} from "contracts/common/lib/BLS.sol";
import {BeaconRootData, ValidatorWitness} from "contracts/common/interfaces/ValidatorWitness.sol";

/**
 * @title CLValidatorVerifier
 * @author Lido
 * @notice
 *
 * Smart contract verifying CL data of validators
 */
abstract contract CLValidatorVerifier {
    // BeaconBlockHeader: state_root field gindex
    uint8 private constant STATE_ROOT_DEPTH = 3;
    uint256 private constant STATE_ROOT_POSITION = 3;
    GIndex public immutable GI_STATE_ROOT = pack((1 << STATE_ROOT_DEPTH) + STATE_ROOT_POSITION, STATE_ROOT_DEPTH);

    // Position (from the end) of parent(slot, proposerIndex) node inside concatenated proof
    uint256 private constant SLOT_PROPOSER_PARENT_PROOF_OFFSET = 2;
    // EIP-4788 system contract
    address public constant BEACON_ROOTS = 0x000F3df6D732807Ef1319fB7B8bB8522d0Beac02;

    // validators[0] gindex before/after fork layout change
    GIndex public immutable GI_FIRST_VALIDATOR_PREV;
    GIndex public immutable GI_FIRST_VALIDATOR_CURR;
    uint64 public immutable PIVOT_SLOT;

    error InvalidSlot();
    error RootNotFound();

    constructor(GIndex _gIFirstValidatorPrev, GIndex _gIFirstValidatorCurr, uint64 _pivotSlot) {
        GI_FIRST_VALIDATOR_PREV = _gIFirstValidatorPrev;
        GI_FIRST_VALIDATOR_CURR = _gIFirstValidatorCurr;
        PIVOT_SLOT = _pivotSlot;
    }

    /// @notice Proves validator[i] under the same EIP-4788 anchor, checks WC
    function _verifyValidator(
        BeaconRootData calldata _beaconRootData,
        ValidatorWitness calldata _vw,
        uint256 _validatorIndex,
        bytes32 _expectedWithdrawalCredentials
    ) internal view virtual {
        _verifySlot(_vw.proofValidator, _beaconRootData.slot, _beaconRootData.proposerIndex);

        bytes32 parentBlockRoot = _getParentBlockRoot(_beaconRootData.childBlockTimestamp);

        GIndex gIndexValidator = concat(GI_STATE_ROOT, _getValidatorGI(_validatorIndex, _beaconRootData.slot));
        bytes32 validatorLeaf = _validatorHashTreeRoot(_vw, _expectedWithdrawalCredentials);
        SSZ.verifyProof({proof: _vw.proofValidator, root: parentBlockRoot, leaf: validatorLeaf, gI: gIndexValidator});
    }

    /// @dev SSZ hash_tree_root(Validator) computed from witness fields.
    function _validatorHashTreeRoot(ValidatorWitness calldata _w, bytes32 _expectedWithdrawalCredentials)
        internal
        view
        returns (bytes32)
    {
        bytes32[8] memory leaves;
        leaves[0] = BLS12_381.pubkeyRoot(_w.pubkey);
        leaves[1] = _expectedWithdrawalCredentials;
        leaves[2] = SSZ.toLittleEndian(_w.effectiveBalance);
        leaves[3] = SSZ.toLittleEndian(_w.slashed ? uint64(1) : 0);
        leaves[4] = SSZ.toLittleEndian(_w.activationEligibilityEpoch);
        leaves[5] = SSZ.toLittleEndian(_w.activationEpoch);
        leaves[6] = SSZ.toLittleEndian(_w.exitEpoch);
        leaves[7] = SSZ.toLittleEndian(_w.withdrawableEpoch);

        bytes32[4] memory l1;
        l1[0] = BLS12_381.sha256Pair(leaves[0], leaves[1]);
        l1[1] = BLS12_381.sha256Pair(leaves[2], leaves[3]);
        l1[2] = BLS12_381.sha256Pair(leaves[4], leaves[5]);
        l1[3] = BLS12_381.sha256Pair(leaves[6], leaves[7]);

        bytes32[2] memory l2;
        l2[0] = BLS12_381.sha256Pair(l1[0], l1[1]);
        l2[1] = BLS12_381.sha256Pair(l1[2], l1[3]);

        return BLS12_381.sha256Pair(l2[0], l2[1]);
    }

    /// @dev Checks that (slot, proposerIndex) parent node is present in the same concatenated proof.
    function _verifySlot(bytes32[] calldata _proof, uint64 _slot, uint64 _proposerIndex) internal view {
        bytes32 parentSlotProposer = BLS12_381.sha256Pair(SSZ.toLittleEndian(_slot), SSZ.toLittleEndian(_proposerIndex));
        if (_proof[_proof.length - SLOT_PROPOSER_PARENT_PROOF_OFFSET] != parentSlotProposer) {
            revert InvalidSlot();
        }
    }

    /// @dev GIndex for Validator[i] given slot (fork-aware).
    function _getValidatorGI(uint256 _offset, uint64 _provenSlot) internal view returns (GIndex) {
        GIndex gI = _provenSlot < PIVOT_SLOT ? GI_FIRST_VALIDATOR_PREV : GI_FIRST_VALIDATOR_CURR;
        return gI.shr(_offset);
    }

    /// @dev Reads parent_beacon_block_root from EIP-4788 by timestamp.
    function _getParentBlockRoot(uint64 _childBlockTimestamp) internal view returns (bytes32) {
        (bool success, bytes memory data) = BEACON_ROOTS.staticcall(abi.encode(_childBlockTimestamp));
        if (!success || data.length == 0) revert RootNotFound();
        return abi.decode(data, (bytes32));
    }
}

contracts/0.8.25/TopUpGateway.sol.content:
// SPDX-FileCopyrightText: 2025 Lido <info@lido.fi>
// SPDX-License-Identifier: GPL-3.0

/* See contracts/COMPILERS.md */
pragma solidity 0.8.25;

import {TopUpData, BeaconRootData, ValidatorWitness} from "contracts/common/interfaces/TopUpWitness.sol";
import {CLValidatorVerifier} from "./CLValidatorVerifier.sol";
import {
    AccessControlEnumerableUpgradeable
} from "contracts/openzeppelin/5.2/upgradeable/access/extensions/AccessControlEnumerableUpgradeable.sol";
import {GIndex} from "contracts/common/lib/GIndex.sol";
import {WithdrawalCredentials} from "contracts/common/lib/WithdrawalCredentials.sol";
import {PausableUntil} from "contracts/common/utils/PausableUntil.sol";

interface ILidoLocator {
    function stakingRouter() external view returns (address);
}

interface IStakingRouter {
    function getStakingModuleWithdrawalCredentials(uint256 _stakingModuleId) external view returns (bytes32);
    function topUp(
        uint256 _stakingModuleId,
        uint256[] calldata _keyIndices,
        uint256[] calldata _operatorIds,
        bytes[] calldata _pubkeys,
        uint256[] calldata _topUpLimits
    ) external;
}

/**
 * @title TopUpGateway
 * @author Lido
 * @notice TopUpGateway is a contract that serves as the entry point for validator top-ups
 */
contract TopUpGateway is CLValidatorVerifier, AccessControlEnumerableUpgradeable, PausableUntil {
    using WithdrawalCredentials for bytes32;

    ILidoLocator internal immutable LOCATOR;

    struct Storage {
        uint64 maxValidatorsPerTopUp; // 64
        uint32 lastTopUpTimestamp; // 32
        uint32 lastTopUpBlock; // 32
        uint16 minBlockDistance; // 16
        uint16 maxRootAge; // 16
        uint64 targetBalanceGwei; // 64
        uint64 minTopUpGwei; // 64
    }

    /// @dev Storage slot: keccak256(abi.encode(uint256(keccak256("lido.TopUpGateway.storage")) - 1)) & ~bytes32(uint256(0xff))
    bytes32 internal constant GATEWAY_STORAGE_POSITION =
        0x22e512057841e2bc1e6d80030c8bb8b4935377af2e64ba9bf8e6a3e88fb32200;

    uint256 internal constant PUBKEY_LENGTH = 48;
    uint256 internal constant FAR_FUTURE_EPOCH = type(uint64).max;
    uint256 public immutable SLOTS_PER_EPOCH;

    bytes32 public constant TOP_UP_ROLE = keccak256("TOP_UP_ROLE");
    bytes32 public constant MANAGE_LIMITS_ROLE = keccak256("MANAGE_LIMITS_ROLE");
    bytes32 public constant PAUSE_ROLE = keccak256("PAUSE_ROLE");
    bytes32 public constant RESUME_ROLE = keccak256("RESUME_ROLE");

    constructor(
        address _lidoLocator,
        GIndex _gIFirstValidatorPrev,
        GIndex _gIFirstValidatorCurr,
        uint64 _pivotSlot,
        uint256 _slotsPerEpoch
    ) CLValidatorVerifier(_gIFirstValidatorPrev, _gIFirstValidatorCurr, _pivotSlot) {
        if (_lidoLocator == address(0)) revert ZeroArgument("_lidoLocator");
        LOCATOR = ILidoLocator(_lidoLocator);
        SLOTS_PER_EPOCH = _slotsPerEpoch;
        _disableInitializers();
    }

    /// @notice Initializes the TopUpGateway proxy with admin, rate limits, and top-up balance parameters.
    /// @param _admin Address to receive DEFAULT_ADMIN_ROLE
    /// @param _maxValidatorsPerTopUp Maximum number of validators per single topUp call
    /// @param _minTopUpBlockDistance Minimum blocks between topUp calls
    /// @param _maxRootAgeSec Maximum age (seconds) of beacon root relative to block.timestamp
    /// @param _targetBalanceGwei Target validator balance ceiling after top-up (in Gwei).
    ///        Top-up amount = targetBalance - currentTotal.
    /// @param _minTopUpGwei Minimum top-up that can be performed (in Gwei). If calculated top-up < minTopUp, returns 0.
    ///        Must be <= _targetBalanceGwei.
    function initialize(
        address _admin,
        uint256 _maxValidatorsPerTopUp,
        uint256 _minTopUpBlockDistance,
        uint256 _maxRootAgeSec,
        uint256 _targetBalanceGwei,
        uint256 _minTopUpGwei
    ) external initializer {
        if (_admin == address(0)) revert ZeroArgument("_admin");
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        _setMaxValidatorsPerTopUp(_maxValidatorsPerTopUp);
        _setMinBlockDistance(_minTopUpBlockDistance);
        _setMaxRootAge(_maxRootAgeSec);
        _setTopUpBalanceLimits(_targetBalanceGwei, _minTopUpGwei);
    }

    /**
     * @notice Resume the contract
     * @dev Reverts if contracts is not paused
     * @dev Reverts if sender has no `RESUME_ROLE`
     */
    function resume() external onlyRole(RESUME_ROLE) {
        _resume();
    }

    /**
     * @notice Pause the contract for a specified period
     * @param _duration pause duration in seconds (use `PAUSE_INFINITELY` for unlimited)
     * @dev Reverts if contract is already paused
     * @dev Reverts if sender has no `PAUSE_ROLE`
     * @dev Reverts if zero duration is passed
     */
    function pauseFor(uint256 _duration) external onlyRole(PAUSE_ROLE) {
        _pauseFor(_duration);
    }

    /**
     * @notice Pause the contract until a specified timestamp
     * @param _pauseUntilInclusive the last second to pause until inclusive
     * @dev Reverts if the timestamp is in the past
     * @dev Reverts if sender has no `PAUSE_ROLE`
     * @dev Reverts if contract is already paused
     */
    function pauseUntil(uint256 _pauseUntilInclusive) external onlyRole(PAUSE_ROLE) {
        _pauseUntil(_pauseUntilInclusive);
    }

    /**
     * @notice Method verifying Merkle proofs on validators and proceeding to top up validators
     * via StakingRouter.topUp(stakingModuleId, keyIndices, operatorIds, pubkeys, topUpLimits)
     * @param _topUps TopUpData structure, containing validators' container fields, pending deposits
     *  and Merkle proofs on inclusion of each container in Beacon State tree
     * @dev Only callable by accounts with TOP_UP_ROLE.
     *
     * validatorIndices MUST be sorted in strictly ascending order. The corresponding keyIndices,
     * operatorIds, validatorWitness and pendingBalanceGwei arrays must be aligned by position
     * to validatorIndices[i].
     *
     * Reverts if:
     *  - the caller doesn't have TOP_UP_ROLE (AccessControl);
     *  - validatorIndices is empty, or any of keyIndices, operatorIds, validatorWitness,
     *    pendingBalanceGwei has a length different from validatorIndices
     *    (`WrongArrayLength`);
     *  - validatorIndices length exceeds maxValidatorsPerTopUp (`MaxValidatorsPerTopUpExceeded`);
     *  - validatorIndices is not strictly increasing (not sorted or contains duplicates) (`InvalidValidatorIndicesSortOrder`);
     *  - fewer than minBlockDistance blocks have passed since the last top-up (`MinBlockDistanceNotMet`);
     *  - the beacon root is older than maxRootAge relative to block.timestamp (`RootIsTooOld`);
     *  - the beacon root childBlockTimestamp is not newer than the last top-up timestamp
     *    (`RootPrecedesLastTopUp`);
     *  - the module's withdrawal credentials are not of type 0x02 (`WrongWithdrawalCredentials`);
     *  - any validator pubkey has a length different from 48 bytes (`WrongPubkeyLength`);
     *  - any validator has activationEpoch > current epoch (derived from beacon root slot) (`ValidatorIsNotActivated`);
     *  - any validator Merkle proof fails verification in CLValidatorVerifier.
     */
    function topUp(TopUpData calldata _topUps) external onlyRole(TOP_UP_ROLE) whenResumed {
        Storage storage $ = _gatewayStorage();

        uint256 validatorsCount = _topUps.validatorIndices.length;
        if (validatorsCount == 0) revert WrongArrayLength();

        if (
            _topUps.keyIndices.length != validatorsCount || _topUps.operatorIds.length != validatorsCount
                || _topUps.validatorWitness.length != validatorsCount
                || _topUps.pendingBalanceGwei.length != validatorsCount
        ) {
            revert WrongArrayLength();
        }

        if (validatorsCount > $.maxValidatorsPerTopUp) {
            revert MaxValidatorsPerTopUpExceeded();
        }

        // Distance is for flexibility in future to control top-up frequency
        _requireBlockDistancePassed();

        // Check proof age
        // 0. _topUps.beaconRootData.childBlockTimestamp is newer than timestamp of last top up
        // 1. _topUps.beaconRootData.childBlockTimestamp is not older than maxRootAge
        _verifyRootAge(_topUps.beaconRootData);

        IStakingRouter stakingRouter = IStakingRouter(LOCATOR.stakingRouter());

        // Find and validate withdrawalCredentials 0x02
        bytes32 withdrawalCredentials = stakingRouter.getStakingModuleWithdrawalCredentials(_topUps.moduleId);
        _requireWithdrawalCredentials02(withdrawalCredentials);

        bytes[] memory pubkeys = new bytes[](validatorsCount);

        uint256[] memory topUpLimits = new uint256[](validatorsCount);

        uint256 totalLimits;

        // Track previous validator index to enforce strictly increasing order inline (see check below).
        uint256 prevValidatorIndex;

        // 1. Evaluate top-up limit based on current balance, pending deposits, and configured limits
        // 2. Verify proof data through CLValidatorProofVerifier
        unchecked {
            for (uint256 i; i < validatorsCount; ++i) {
                // For each validator
                ValidatorWitness calldata vw = _topUps.validatorWitness[i];

                if (vw.pubkey.length != PUBKEY_LENGTH) {
                    revert WrongPubkeyLength();
                }

                // Require validatorIndices to be strictly increasing (rejects duplicates and unsorted input).
                uint256 validatorIndex = _topUps.validatorIndices[i];
                if (i != 0 && validatorIndex <= prevValidatorIndex) {
                    revert InvalidValidatorIndicesSortOrder();
                }
                prevValidatorIndex = validatorIndex;

                _verifyValidatorWasActivated(_topUps.beaconRootData.slot, vw);

                _verifyValidator(_topUps.beaconRootData, vw, validatorIndex, withdrawalCredentials);

                pubkeys[i] = vw.pubkey;

                // calculate top up limit accounting for current balance and pending deposits
                topUpLimits[i] = _evaluateTopUpLimit(vw, _topUps.pendingBalanceGwei[i]) * 1 gwei;
                totalLimits += topUpLimits[i];
            }
        }

        // Proceed to StakingRouter
        stakingRouter.topUp(_topUps.moduleId, _topUps.keyIndices, _topUps.operatorIds, pubkeys, topUpLimits);

        if (totalLimits > 0) {
            _setLastTopUpData();
        }
    }

    /**
     * @notice Returns the timestamp when last top up happened
     */
    function getLastTopUpTimestamp() external view returns (uint256) {
        return _gatewayStorage().lastTopUpTimestamp;
    }

    /**
     * @notice Returns the allowed amount of validators per top up
     */
    function getMaxValidatorsPerTopUp() external view returns (uint256) {
        return _gatewayStorage().maxValidatorsPerTopUp;
    }

    /**
     * @notice Returns the min block distance that should pass from last top up
     */
    function getMinBlockDistance() external view returns (uint256) {
        return _gatewayStorage().minBlockDistance;
    }

    /**
     * @notice Returns true if enough blocks have passed since the last top-up
     *         (or no top-up has happened yet).
     */
    function isBlockDistancePassed() external view returns (bool) {
        return _isBlockDistancePassed();
    }

    /**
     * @notice Returns the maximum age (seconds) of beacon root relative to block.timestamp
     */
    function getMaxRootAge() external view returns (uint256) {
        return _gatewayStorage().maxRootAge;
    }

    /**
     * @notice Returns target validator balance ceiling after top-up (in Gwei)
     */
    function getTargetBalanceGwei() external view returns (uint256) {
        return _gatewayStorage().targetBalanceGwei;
    }

    /**
     * @notice Returns minimum top-up that can be performed (in Gwei).
     */
    function getMinTopUpGwei() external view returns (uint256) {
        return _gatewayStorage().minTopUpGwei;
    }

    /**
     * @notice Set max validators per top up value
     * @param _newValue Max validators per top up value
     */
    function setMaxValidatorsPerTopUp(uint256 _newValue) external onlyRole(MANAGE_LIMITS_ROLE) {
        _setMaxValidatorsPerTopUp(_newValue);
    }

    /**
     * @notice Set min block distance
     * @param _newValue Min block distance
     */
    function setMinBlockDistance(uint256 _newValue) external onlyRole(MANAGE_LIMITS_ROLE) {
        _setMinBlockDistance(_newValue);
    }

    /**
     * @notice Set targetBalanceGwei and minTopUpGwei values
     * @param _targetBalanceGwei target validator balance ceiling after top-up (in Gwei)
     * @param _minTopUpGwei  minimum top-up that can be performed (in Gwei).
     */
    function setTopUpBalanceLimits(uint256 _targetBalanceGwei, uint256 _minTopUpGwei)
        external
        onlyRole(MANAGE_LIMITS_ROLE)
    {
        _setTopUpBalanceLimits(_targetBalanceGwei, _minTopUpGwei);
    }

    /// @notice Sets the maximum allowed age of beacon root relative to current block timestamp
    /// @param _newValue Maximum age in seconds
    function setMaxRootAge(uint256 _newValue) external onlyRole(MANAGE_LIMITS_ROLE) {
        _setMaxRootAge(_newValue);
    }

    function _isBlockDistancePassed() internal view returns (bool) {
        Storage storage $ = _gatewayStorage();
        return $.lastTopUpBlock == 0 || block.number - $.lastTopUpBlock >= $.minBlockDistance;
    }

    function _requireBlockDistancePassed() internal view {
        if (!_isBlockDistancePassed()) {
            revert MinBlockDistanceNotMet();
        }
    }

    function _requireWithdrawalCredentials02(bytes32 _wc) internal pure {
        if (!_wc.isType2()) {
            revert WrongWithdrawalCredentials();
        }
    }

    function _setLastTopUpData() internal {
        Storage storage $ = _gatewayStorage();
        $.lastTopUpTimestamp = uint32(block.timestamp);
        $.lastTopUpBlock = uint32(block.number);
        emit LastTopUpChanged(block.timestamp);
    }

    function _setMaxRootAge(uint256 _newValue) internal {
        if (_newValue == 0) revert ZeroValue();
        if (_newValue > type(uint16).max) revert TooLargeValue();
        _gatewayStorage().maxRootAge = uint16(_newValue);

        emit MaxRootAgeChanged(_newValue);
    }

    function _setMaxValidatorsPerTopUp(uint256 _newValue) internal {
        if (_newValue == 0) revert ZeroValue();
        if (_newValue > type(uint64).max) revert TooLargeValue();
        _gatewayStorage().maxValidatorsPerTopUp = uint64(_newValue);
        emit MaxValidatorsPerTopUpChanged(_newValue);
    }

    function _setMinBlockDistance(uint256 _newValue) internal {
        if (_newValue == 0) revert ZeroValue();
        if (_newValue > type(uint16).max) revert TooLargeValue();
        _gatewayStorage().minBlockDistance = uint16(_newValue);
        emit MinBlockDistanceChanged(_newValue);
    }

    function _setTopUpBalanceLimits(uint256 _targetBalanceGwei, uint256 _minTopUpGwei) internal {
        if (_targetBalanceGwei == 0 || _minTopUpGwei == 0) revert ZeroValue();
        if (_targetBalanceGwei > type(uint64).max || _minTopUpGwei > type(uint64).max) revert TooLargeValue();
        if (_minTopUpGwei > _targetBalanceGwei) revert MinTopUpExceedsTarget();

        Storage storage $ = _gatewayStorage();
        $.targetBalanceGwei = uint64(_targetBalanceGwei);
        $.minTopUpGwei = uint64(_minTopUpGwei);
        emit TopUpBalanceLimitsChanged(_targetBalanceGwei, _minTopUpGwei);
    }

    function _verifyRootAge(BeaconRootData calldata _beaconRootData) internal view {
        if (block.timestamp > _beaconRootData.childBlockTimestamp + _gatewayStorage().maxRootAge) {
            revert RootIsTooOld();
        }

        if (_beaconRootData.childBlockTimestamp <= _gatewayStorage().lastTopUpTimestamp) {
            revert RootPrecedesLastTopUp();
        }
    }

    function _verifyValidatorWasActivated(uint64 _slot, ValidatorWitness calldata _w) internal view {
        // header slot epoch
        uint64 epoch = uint64(_slot / SLOTS_PER_EPOCH);
        if (_w.activationEpoch > epoch) revert ValidatorIsNotActivated();
    }

    function _evaluateTopUpLimit(ValidatorWitness calldata _validator, uint256 _pendingBalanceGwei)
        internal
        view
        returns (uint256)
    {
        // withdrawableEpoch is intentionally not checked: per the consensus spec it is only ever set
        // together with exitEpoch, so `exitEpoch != FAR_FUTURE_EPOCH` already covers the exiting/exited case.
        if (_validator.exitEpoch != FAR_FUTURE_EPOCH || _validator.slashed) {
            return 0;
        }

        Storage storage $ = _gatewayStorage();
        uint256 currentTotal = _validator.effectiveBalance + _pendingBalanceGwei;
        if (currentTotal >= $.targetBalanceGwei) return 0;

        uint256 topUpLimit = $.targetBalanceGwei - currentTotal;
        if (topUpLimit < $.minTopUpGwei) return 0;

        return topUpLimit;
    }

    function _gatewayStorage() internal pure returns (Storage storage $) {
        bytes32 position = GATEWAY_STORAGE_POSITION;
        assembly ("memory-safe") {
            $.slot := position
        }
    }

    event MaxValidatorsPerTopUpChanged(uint256 newValue);
    event MinBlockDistanceChanged(uint256 newValue);
    event LastTopUpChanged(uint256 newValue);
    event MaxRootAgeChanged(uint256 newValue);
    event TopUpBalanceLimitsChanged(uint256 targetBalanceGwei, uint256 minTopUpGwei);

    error ZeroValue();
    error ZeroArgument(string argument);
    error TooLargeValue();
    error RootIsTooOld();
    error RootPrecedesLastTopUp();
    error WrongArrayLength();
    error MaxValidatorsPerTopUpExceeded();
    error WrongWithdrawalCredentials();
    error WrongPubkeyLength();
    error MinBlockDistanceNotMet();
    error InvalidValidatorIndicesSortOrder();
    error ValidatorIsNotActivated();
    error MinTopUpExceedsTarget();
}

